require __DIR__.'/../app/bootstrap.php';security_headers();student_private_headers();$db=database();$student=student_account_current($db);if(!$student){header('Location: /aluno/login.php?next=%2Faluno%2Fcalibracao.php',true,303);exit;}$studentId=(int)$student['id'];try{student_tool_require($db,$studentId,'calibration');}catch(Throwable){http_response_code(403);exit('Ferramenta indisponível.');}$error='';if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){if(!verify_csrf('student-calibration',$_POST['_csrf']??null))$error='Solicitação inválida.';else try{student_calibration_save($db,$studentId,$_POST);header('Location: /aluno/calibracao.php?saved=1',true,303);exit;}catch(Throwable $e){$error=$e->getMessage();}}$rows=student_calibrations($db,$studentId);student_shell_start('Calibração',null,$student);?>
<div class="student-appbar"><a class="student-back" href="/aluno/ferramentas.php">← Ferramentas</a></div><p class="student-kicker">Referência pessoal</p><h1 class="student-title">Calibração</h1><p class="student-lead">Guarde o tempo de formação do branco para uma configuração que você realmente testou.</p><?php if(isset($_GET['saved'])):?><p class="ui-alert ui-alert-notice">Calibração salva.</p><?php endif;?><?php if($error):?><p class="ui-alert ui-alert-error"><?=h($error)?></p><?php endif;?><section class="student-tool-workspace"><form method="post" class="student-form-grid"><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-calibration'))?>"><label class="form-field student-span-2">Nome<input name="label" required placeholder="Ex.: HR-U · Parodinal · 26 °C"></label><label class="form-field">Filme<input name="film"></label><label class="form-field">Revelador<input name="developer"></label><label class="form-field">Preparo / diluição<input name="preparation"></label><label class="form-field">Temperatura<input name="temperature"></label><label class="form-field">Pré-banho<input name="prebath"></label><label class="form-field">Tempo do branco<input name="white_time" required></label><details class="student-optional-fields student-span-2"><summary>Anotações</summary><label class="form-field"><textarea name="notes" rows="3"></textarea></label></details><div class="student-actions student-span-2"><button class="button button-primary" type="submit">Salvar calibração</button></div></form></section><section class="student-section"><div class="student-section-heading"><div><p class="student-kicker">Referências</p><h2 class="student-subtitle">Suas calibrações</h2></div></div><?php if(!$rows):?><div class="student-empty">Nenhuma calibração salva.</div><?php else:?><div class="student-test-list"><?php foreach($rows as $row):?><article class="student-simple-row"><div><h3><?=h((string)$row['label'])?></h3><p><?=h(implode(' · ',array_filter([(string)$row['film'],(string)$row['developer'],(string)$row['preparation'],(string)$row['temperature']])))?></p></div><strong><?=h((string)$row['white_time'])?></strong></article><?php endforeach;?></div><?php endif;?></section><?php student_shell_end();